export type LeaderboardEntry = {
  id: string;
  address: string;
  username?: string;
  grade?: string;
  /** Hot-streak tier (trailing-7d cross-sectional percentile); a separate axis from the all-time grade. Omitted when there is no recent activity. */
  streak_tier?: "hot" | "rising" | "neutral" | "cooling" | "cold";
  score?: number;
  /** All-time P&L in USD (total_pnl), including unrealized open positions. Kept for back-compat; prefer realized_pnl for the banked figure. */
  pnl?: number;
  /** Native realized P&L plus credited maker and taker rebates in USD, with fees already included. The exact numeric value is truncated toward zero to cents before JSON conversion. Wallets without a native snapshot retain their historical stored realized P&L. Omitted when the native snapshot has no net realized value. */
  realized_pnl?: number;
  /** Full-history both-sides USD cash volume from a verified Polymarket user-volume observation. Omitted without coverage. */
  volume?: number;
  markets_traded?: number;
  /** The wallet's win rate across ALL categories, not the filtered one. ?category= decides WHICH wallets are listed (the wallet must be ranked in that category); it does not rescope this field, so a soccer-filtered list still reports each wallet's overall rate. For a per-category record use GET /api/v1/trader/{address}/categories. */
  win_rate?: number;
  /** Observed trading style identifier. New rows use two_sided, category_focused, high_activity, diversified, mixed, or unclassified. Historical identifiers remain readable during normal reclassification; style does not predict skill or intent. */
  strategy_type?: string;
  /** Provider platform. Always polymarket. */
  platform: "polymarket";
  last_active?: string;
};

/** Provider-first bucketed OHLC price candles for a market's outcome tokens, derived from the stored token_price_snapshots series (covers open and resolved markets). */
export type MarketCandles = {
  /** Market condition id the candles were read for. */
  condition_id: string;
  /** Bucketing granularity that produced these candles. */
  resolution: "1d" | "1w";
  /** One entry per present provider token (YES first, then NO); empty when no tokens have been fetched yet. */
  outcomes: OutcomeCandles[];
};

export type MarketFlow = {
  market: {
    id: string;
    condition_id: string;
    title: string;
    slug: string | null;
    category: string | null;
    /** Provider platform. Always polymarket, or null when the row carries no stored value. */
    platform: "polymarket" | null;
  };
  /** Outcome-aware flow from all tracked whale trades in the window, without a grade filter. BUY YES and SELL NO add net exposure; BUY NO and SELL YES subtract it. Gross buy/sell volumes count both outcomes. Top positions are separately graded. Direction uses unrounded net: negative is NO, otherwise YES; the zero tie-break is not conviction. Canonical; smart_money is a deprecated byte-identical alias. */
  sharp_money: {
    net_flow_usd: number;
    direction: "YES" | "NO";
    /** The Polymarket CLOB token id (ERC1155 asset id, decimal string) for the net-flow direction outcome; null when unavailable (e.g. unsynced markets). */
    token_id: string | null;
    /** Canonical key since #16304 (Polymarket's noun is large trade); whale_trade_count is its deprecated spelling, emitted beside it with the same value. */
    large_trade_count?: number;
    whale_trade_count: number;
    buy_volume_usd: number;
    sell_volume_usd: number;
    top_positions: ({
      id: string;
      address: string;
      username: string | null;
      grade: string | null;
      side: "YES" | "NO";
      /** The Polymarket CLOB token id (ERC1155 asset id, decimal string) for this outcome; null when unavailable (e.g. unsynced markets). */
      token_id: string | null;
      size_usd: number;
    })[];
    /** Age of the oldest stored position snapshot behind top_positions: the minimum wallet sync clock over the positions this body publishes. The roster is a stored read rather than a live one, and graded wallets sit on different sync tiers, so this names how current the whole roster is; the response is no fresher than this timestamp. Null when the roster is empty or no published position carries a sync clock. It does not date net_flow_usd, the volumes or the trade counts, which come from large-trade event times. */
    oldest_snapshot_as_of: string | null;
  };
  /**
   * Deprecated alias of sharp_money; byte-identical and retained for backward compatibility.
   * @deprecated
   */
  smart_money: {
    net_flow_usd: number;
    direction: "YES" | "NO";
    /** The Polymarket CLOB token id (ERC1155 asset id, decimal string) for the net-flow direction outcome; null when unavailable (e.g. unsynced markets). */
    token_id: string | null;
    /** Canonical key since #16304 (Polymarket's noun is large trade); whale_trade_count is its deprecated spelling, emitted beside it with the same value. */
    large_trade_count?: number;
    whale_trade_count: number;
    buy_volume_usd: number;
    sell_volume_usd: number;
    top_positions: ({
      id: string;
      address: string;
      username: string | null;
      grade: string | null;
      side: "YES" | "NO";
      /** The Polymarket CLOB token id (ERC1155 asset id, decimal string) for this outcome; null when unavailable (e.g. unsynced markets). */
      token_id: string | null;
      size_usd: number;
    })[];
    /** Age of the oldest stored position snapshot behind top_positions: the minimum wallet sync clock over the positions this body publishes. The roster is a stored read rather than a live one, and graded wallets sit on different sync tiers, so this names how current the whole roster is; the response is no fresher than this timestamp. Null when the roster is empty or no published position carries a sync clock. It does not date net_flow_usd, the volumes or the trade counts, which come from large-trade event times. */
    oldest_snapshot_as_of: string | null;
  };
  timeframe: string;
};

export type MarketHolder = {
  /** Composite `pos_<wallet>:<condition_id>:<outcome_index>`, the same id `GET /api/v1/positions` gives this leg. */
  id: string;
  /** `trd_`-prefixed trader id, accepted by `GET /api/v1/trader/{address}`. */
  trader_id: string;
  /** Lowercased proxy wallet. */
  address: string;
  /** Polymarket's public display name from the same holder snapshot; null for a private wallet, which the provider redacts at the source. */
  name: string | null;
  /** The outcome this wallet nets to. A wallet holding both outcomes is listed once, on its net side; see `other_outcome_shares`. */
  side: "YES" | "NO";
  /** Polymarket CLOB token id (ERC1155 asset id, decimal string) for `side`; null when the market has no stored token id. */
  token_id: string | null;
  /** All-time trader grade. This route lists the S/A/B cohort only, the same cohort a Pick of the Day roster lists. */
  grade: "S" | "A" | "B" | null;
  /** Shares held on `side`, from the complete provider scan. */
  shares: number;
  /** Polymarket's own currentValue for this leg, in USD. Null when the snapshot predates the value map. */
  current_value_usd: number | null;
  /** Shares on the other outcome when the wallet holds both. Absent when the wallet is one-sided. */
  other_outcome_shares?: number;
  /** The wallet's last recorded trade anywhere, null when unknown. */
  last_traded_at: string | null;
  /** This wallet's win rate in the market's canonical category (`market.category`): the share of its resolved markets in that category whose realized P&L closed positive, as a 0..1 fraction. Present only with `category_win_rate_status` = `measured`. The same read `GET /api/v1/trader/{address}/categories` serves per wallet. */
  category_win_rate?: number;
  /** The two counts `category_win_rate` is the ratio of, from the same row: `wins / decided` equals the rate. Every resolved Polymarket market the wallet traded in the market's canonical category, at any position size, rebuilt daily. Present only with `category_win_rate_status` = `measured`. */
  category_win_record?: {
    /** Resolved markets in the category that this wallet closed with a profit. */
    wins: number;
    /** Resolved markets in the category that this wallet closed with a profit or a loss. A market resolved at zero realized P&L is in neither count. */
    decided: number;
  };
  /** For an esports market, the game `category_win_rate` and `category_win_record` were measured in: `LoL`, `CS2`, `Dota 2`, `Valorant`, `Call of Duty`, `Honor of Kings`, `Mobile Legends: Bang Bang`, `Overwatch`, `Rainbow Six Siege`, `Rocket League` or `StarCraft II`. Present only when the wallet's record in that game clears the 5-resolved-market floor, in which case the rate and record are the game's rather than the `Esports` bucket's. Absent when the rate is the bucket's (the wallet's game history is under the floor), on every non-esports market, and beside every non-measured status. Label the rate with this when present and with the market's `category` otherwise. */
  category_win_rate_game?: string;
  /** Why `category_win_rate` is present or absent: `measured` (rate present), `not_enough_data` (under the floor of 5 decided markets in the category), or `unavailable` (the market has no canonical category, or the read failed; retry later). Always present on this route. */
  category_win_rate_status: "measured" | "not_enough_data" | "unavailable";
  category_evidence?: HolderCategoryEvidence;
  /** Days since this wallet's first trade. The five badge fields are present together, only for a wallet that draws at least one badge. */
  wallet_age_days?: number | null;
  /** True when the wallet's first trade was under 30 days ago. */
  is_new_wallet?: boolean;
  /** Distinct markets the wallet has traded. */
  markets_traded?: number | null;
  /** True when the wallet is flagged as automated. */
  is_bot?: boolean;
  /** The wallet's X handle without the @, when linked. */
  x_username?: string | null;
};

export type MarketHoldersMarket = {
  /** `mkt_`-prefixed market id. */
  id: string;
  condition_id: string;
  title: string | null;
  slug?: string;
  event_slug?: string;
  /** The canonical category bucket `category_win_rate` is measured in. */
  category: string | null;
  outcome_yes: string | null;
  outcome_no: string | null;
  token_id_yes: string | null;
  token_id_no: string | null;
  end_date?: string;
  /** A settled market's roster is whatever the provider still lists as open; it empties as holders redeem. */
  status: "open" | "closed" | "resolved";
};

export type MarketHoldersScan = {
  /** `cached`: the shared holder snapshot, at most 180 s old at compute time. `live`: the provider answered a fresh complete walk for this compute. */
  source: "cached" | "live";
  /** Always true on a served roster. An incomplete or unstable scan is a 503, never a partial list. */
  complete: boolean;
  /** When the provider walk that produced the holder population finished. */
  fetched_at: string | null;
  /** Every distinct wallet the complete walk saw with open shares, graded or not. The roster lists the graded S/A/B subset. */
  wallet_count: number;
};

export type MarketHoldersSideGrades = {
  s: number;
  a: number;
  b: number;
};

/** Roster totals BEFORE any `outcome` or `min_grade` filter, so a page always knows the whole market it was cut from. */
export type MarketHoldersTotals = {
  /** Distinct graded wallets with net exposure; a two-sided wallet counts once. */
  graded_count: number;
  yes_count: number;
  no_count: number;
  yes_shares: number;
  no_shares: number;
  /** Polymarket currentValue summed over the graded wallets netting YES. */
  yes_usd: number;
  /** Polymarket currentValue summed over the graded wallets netting NO. */
  no_usd: number;
  yes_grades: MarketHoldersSideGrades;
  no_grades: MarketHoldersSideGrades;
};

export type MarketSearchResult = {
  id: string;
  condition_id: string;
  title: string;
  slug: string | null;
  category: string | null;
  /** Provider platform. Always polymarket, or null when the row carries no stored value. */
  platform: "polymarket" | null;
  /** closed once Polymarket has closed trading or the market has resolved; active otherwise. The same rule labels a market on markets/search, markets/explore and market/{condition_id}/snapshot. */
  status: "active" | "closed";
};

export type MarketSnapshot = {
  market: {
    id: string;
    condition_id: string;
    provider: string;
    title: string | null;
    slug: string | null;
    page_slug: string | null;
    event_slug: string | null;
    category: string | null;
    /** closed once Polymarket has closed trading or the market has resolved; active otherwise. The same rule labels a market on markets/search, markets/explore and market/{condition_id}/snapshot. */
    status: "active" | "closed";
    description: string | null;
    image: string | null;
    /** Polymarket series slug from the canonical identity row, null when unavailable. A sports series identifies a league and must not be used as a per-matchup grouping key. */
    series_slug: string | null;
    market_type: string | null;
    market_result: string | null;
    created_at: string | null;
    end_date: string | null;
    resolved_at: string | null;
  };
  outcomes: ({
    side: "yes" | "no";
    label: string;
    token_id?: string;
    current_price?: number;
    top_of_book: MarketSnapshotTopOfBook;
  })[];
  liquidity: {
    source: string;
    volume_usd: number | null;
    liquidity_usd: number | null;
    volume_24h_usd: number | null;
    /** Always null. Polymarket snapshot prices come from outcome top-of-book midpoints. */
    last_price: number | null;
  };
  sports: {
    status: "fresh" | "stale" | "not_live" | "unavailable";
    source: string;
    live_match_key?: string;
    live_league_key?: string;
    /** Live-score period and elapsed may be omitted when unavailable (older responses use null). A score entry may omit full_name when it equals team; fall back to team. Distinct aliases and score admission markers are preserved. */
    live_score?: Record<string, unknown>;
    reason?: string;
  };
  freshness: {
    market_data: MarketSnapshotFreshness;
    top_of_book: MarketSnapshotFreshness;
    /** Freshness requires the dedicated two-second post-publication marker to match the retained vintage and non-invalidated data timestamp; timestamp presence alone is insufficient. as_of records compute start, so stale_after_s is omitted rather than implying as_of plus two seconds. Missing membership is not_live only in a fresh source; stale membership remains stale and unreadable source data is unavailable. Repeated lookups reuse the shared payload and typed index for an unchanged generation. */
    live_sports: MarketSnapshotFreshness;
  };
  /** Price and spread trust metadata. Present only when expand=trust or expand[]=trust is requested. */
  trust?: MarketSnapshotTrust;
};

export type MarketSnapshotFreshness = {
  status: "fresh" | "stale" | "available" | "not_live" | "unavailable";
  source: string;
  as_of?: string;
  /** Age-relative freshness bound when known. Omitted for live_sports: its as_of records compute start, while its two-second freshness marker starts at publication. */
  stale_after_s?: number;
  reason?: string;
};

export type MarketSnapshotTopOfBook = {
  status: "available" | "unavailable";
  source: string;
  best_bid?: number;
  best_ask?: number;
  spread_bps?: number;
  bid_depth_usdc?: number;
  ask_depth_usdc?: number;
  reason?: string;
};

/** Price and spread trust metadata returned only when GET /api/v1/market/{condition_id}/snapshot includes expand=trust. */
export type MarketSnapshotTrust = {
  current_price: TrustMetadata;
  spread_bps: TrustMetadata;
};

export type McpJsonRpcError = {
  jsonrpc: "2.0";
  id?: string | number | null;
  error: {
    code: number;
    message: string;
    /** Optional JSON-serializable error data. */
    data?: Record<string, unknown> | unknown[] | string | number | boolean | null;
  };
};

/** One outcome token's bucketed candle series. */
export type OutcomeCandles = {
  /** Provider CLOB token id the candles were read for. */
  token_id: string;
  /** Canonical side label. */
  outcome: "YES" | "NO";
  /** OHLC candles for this outcome token, ascending by bucket start. */
  candles: Candle[];
};

export type PickHolder = {
  address: string;
  name: string | null;
  /** All-time trader grade (S, A, B, C, D, F). */
  grade: string | null;
  /** The wallet's most recent recorded trade time, stamped at serve time from its current trader record rather than frozen with the pick. Always sent; null when no trade time is recorded. */
  last_traded_at: string | null;
  /** 0xinsider profile path segment this wallet links to: `@<username>` when that username resolves to this wallet alone, otherwise the lowercase wallet. Percent-encode the part after `@` and append to `https://0xinsider.com/profile/`. Stamped at serve time; absent on a body cached before the field shipped. */
  profile_segment?: string;
  shares: number;
  /** USD entry value of this wallet's position: `shares` times the pick's frozen `backed_price`. An entry valuation, never a live balance or the provider's current value. Omitted when the holder snapshot has no valid price. */
  entry_value_usd?: number;
  /** This wallet's win rate in the pick's canonical category bucket (the pick's `category` field, e.g. Basketball -- label the rate with it, never with the narrower `display_category` league, except when `category_win_rate_game` is present, in which case the rate is that game's and is labelled with it): the share of the wallet's resolved markets in that category whose realized P&L closed positive, as a 0..1 fraction. Present only with `category_win_rate_status` = `measured`, on `display_holders` entries, and only when the wallet clears the resolved-market floor; recomputed at serve time from the current category read model, not frozen with the pick. Absent on `holders` entries, legacy rows, and payloads predating the field. */
  category_win_rate?: number;
  /** The two counts `category_win_rate` is the ratio of, read from the same row: `wins / decided` equals the rate. Counts every resolved Polymarket market the wallet traded in the pick's canonical category (or in its game, when `category_win_rate_game` is present), at any position size; the counts are rebuilt daily. Present only with `category_win_rate_status` = `measured`; absent otherwise and on payloads predating the field. */
  category_win_record?: {
    /** Resolved markets in the category that this wallet closed with a profit. */
    wins: number;
    /** Resolved markets in the category that this wallet closed with a profit or a loss. A market resolved at zero realized P&L is in neither count. */
    decided: number;
  };
  /** For an esports pick, the game `category_win_rate` and `category_win_record` were measured in, by the same name the pick's `display_category` uses for it: `LoL`, `CS2`, `Dota 2`, `Valorant`, `Call of Duty`, `Honor of Kings`, `Mobile Legends: Bang Bang`, `Overwatch`, `Rainbow Six Siege`, `Rocket League` or `StarCraft II`. Present only when the wallet's record in that game clears the 5-resolved-market floor, in which case the rate and record are the game's rather than the `Esports` bucket's. Absent when the rate is the bucket's (the wallet's game history is under the floor), on every non-esports pick, beside every non-measured status, and on payloads predating the field. Label the rate with this when present and with `category` otherwise. */
  category_win_rate_game?: string;
  /** Why `category_win_rate` is present or absent on a `display_holders` entry: `measured` (rate present), `not_enough_data` (the wallet is below the resolved-market floor of 5 in the category), or `unavailable` (the annotation read failed; retry later). Absent entirely on `holders` entries, legacy rows, and payloads predating the field -- absence means the roster was never annotated, not a small sample. */
  category_win_rate_status?: "measured" | "not_enough_data" | "unavailable";
  /** Days since this wallet's first trade. Stamped at serve time from the wallet's current trader record, never frozen with the pick. The five badge fields are present together, and only for a wallet that carries at least one badge; all absent means no badge, or a body cached before the fields shipped. */
  wallet_age_days?: number | null;
  /** True when the wallet's first trade was under 30 days ago. Stamped at serve time from the wallet's current trader record, never frozen with the pick. The five badge fields are present together, and only for a wallet that carries at least one badge; all absent means no badge, or a body cached before the fields shipped. */
  is_new_wallet?: boolean;
  /** Distinct markets this wallet has traded. Stamped at serve time from the wallet's current trader record, never frozen with the pick. The five badge fields are present together, and only for a wallet that carries at least one badge; all absent means no badge, or a body cached before the fields shipped. */
  markets_traded?: number | null;
  /** True when the wallet has traded 10,000 or more distinct markets, the breadth floor 0xinsider uses to mark automated wallets. It is a breadth rule, not proof of automation. Stamped at serve time from the wallet's current trader record, never frozen with the pick. The five badge fields are present together, and only for a wallet that carries at least one badge; all absent means no badge, or a body cached before the fields shipped. */
  is_bot?: boolean;
  /** The wallet's X handle from its Polymarket profile, normalized to 1-15 characters of [A-Za-z0-9_] with no `@`. Link it as `https://x.com/<handle>`. Stamped at serve time from the wallet's current trader record, never frozen with the pick. The five badge fields are present together, and only for a wallet that carries at least one badge; all absent means no badge, or a body cached before the fields shipped. */
  x_username?: string | null;
};

export type PickOfTheDay = {
  /** Always 'full' for an authenticated Pro key. */
  state: "full";
  /** The pick's local publication date (YYYY-MM-DD). */
  pick_date?: string;
  /**
   * Deprecated compatibility daily release slot; use pick_id for identity and publication_order for scheduling.
   * @deprecated
   */
  pick_rank?: number;
  /** Published picks for this product day in the returned display order. Use pick_id for identity. */
  picks?: PickOfTheDay[];
  /** Number of items in `picks`: the proof-readable picks. Picks held in `proof_pending_picks` are not counted. */
  pick_count?: number;
  /** Same-day picks selected but not yet released, ordered by pick_rank. Additive and optional: present only while at least one unreleased slot exists. Each slot exposes only its rank and schedule -- no market identity before release. Schedule the next read from the earliest release_at instead of polling. */
  scheduled_picks?: ScheduledPickSlot[];
  /** Human-readable matchup (e.g. "Portugal vs. Uzbekistan"). */
  matchup?: string;
  /** Recorded canonical sport category. Prefer display_category for the public competition label. */
  category?: string;
  /** Frozen public presentation category: the competition the Polymarket event belongs to. A curated label comes first -- an official league (e.g. "WNBA" or "UFC"), the esports title (e.g. "CS2", "LoL", "Dota 2" or "Valorant"), or a soccer competition (e.g. "LaLiga", "Premier League", "Serie A" or "UEFA Champions League"); any other competition carries the provider's own competition name without its season year (e.g. "UEFA Nations League", "ATP" or "Wimbledon"). It equals category only when the provider names no competition. An esports pick keeps the pooled "Esports" bucket in category, so a per-title label never implies a per-title measured cohort. Additive and optional for mixed-version client compatibility. */
  display_category?: string;
  /** Provider platform. Always polymarket. */
  platform?: "polymarket";
  /** The pick's stored release instant. Normally the current provider kickoff minus one hour; an operator may override it. The actual publish instant can trail it because of worker or claim delay. */
  release_at?: string;
  /** True only before the pick's stored release instant (a pre-release embargo flag); effectively always false on a served, already-published pick. To detect that the backed game has kicked off, use `game_started`. */
  is_locked?: boolean;
  /** True once the backed game's kickoff has passed (kickoff <= now). When true the snapshotted pre-game price is no longer actionable. Absent for a legacy pick with no stored kickoff (treat as not-started). */
  game_started?: boolean;
  /** Whether the backed game is over according to the cached live scoreboard, read at serve time. Tells a finished game from one still in play before `outcome` settles. Omitted when the pick has no event slug or no scoreboard is cached for it; absence is unknown, never false. */
  game_ended?: boolean;
  /** Settlement outcome of the backed side; 'pending' until the market resolves. */
  outcome?: "pending" | "win" | "loss" | "void";
  /** Pre-formatted SETTLEMENT STATUS for display: "Win" / "Loss" / "Void" / "Pending" -- the outcome enum above as a label. Convenience only; outcome is the source value. NOTE: this is the win/loss STATUS, not the backed side. The backed side is pick_outcome_label ("Belgium (-2.5)") -- a different field answering a different question. */
  outcome_display?: string;
  /** The backed side phrased as a bet: a team for a moneyline (e.g. "Portugal"), the handicap line for a spread (e.g. "Belgium (-2.5)"), or "{team} to advance" for a knockout advancement market (e.g. "Spain to advance"). */
  pick_outcome_label?: string;
  /** The Polymarket CLOB token id (ERC1155 asset id, decimal string) for the backed outcome; omitted when unavailable (e.g. unsynced markets). */
  token_id?: string;
  /** The backed side phrased as a bet (e.g. "Portugal to win"). */
  position?: string;
  /** One-line summary of which side sharp money is backing. Required on every item in `picks`: a current-day published pick whose required holder proof is not safely readable is listed in `proof_pending_picks` instead of being served with a partial success shape or a synthetic zero, and the route returns 503 read_model_warming only when no published pick has readable proof. */
  side_summary?: string;
  /** S/A wallet count on the backed side in the public V1 compatibility projection. */
  sharp_wallet_count?: number;
  /**
   * Deprecated spelling of sharp_wallet_count with the same value.
   * @deprecated
   */
  smart_wallet_count?: number;
  /** Best recorded S/A grade in the public V1 compatibility projection. */
  top_grade?: string;
  /** Recorded sharp-money magnitude in USD when available. */
  sharp_usd?: number;
  /**
   * Deprecated spelling of sharp_usd with the same value.
   * @deprecated
   */
  smart_usd?: number;
  /** Frozen pre-game probability (0..1) for the backed side, written once at publication. It is the Polymarket CLOB order book midpoint at release, not an executed fill: a buyer lifts the ask, so a subscriber's own entry is usually a little worse than this price. */
  backed_price?: number;
  /** Full-only disclosure when backed_price was recovered from provider history within 30 seconds before publication. Render beside the price. Absent for ordinary publication captures and teasers; this is a historical reference, not an executed fill. */
  entry_price_note?: string;
  /** Pre-formatted backed_price as cents-on-the-dollar odds, to ONE decimal: "62.0c" / "99.9c". Never rounded to a whole cent -- a 99.9c favorite is not a 100c certainty. Convenience only; backed_price is the source value. Omitted when backed_price is. */
  odds_display?: string;
  /** The flat stake the published record puts on every pick, in USD: 1000 since 2026-09-22 (it was 100 before). Present exactly when return_usd is, so a reader never has to know the stake from anywhere else. */
  stake_usd?: number;
  /** Gross return of stake_usd at the frozen midpoint price (stake_usd / backed_price). A real fill pays the ask, so an executed stake usually returns a little less. Omitted with backed_price. */
  return_usd?: number;
  /** The same return on a literal $100 (100 / backed_price), kept for compatibility: the field predates stake_usd and its name promises the $100 basis, so a client that scales it to its own stake stays right. Present exactly when return_usd is. */
  return_per_100?: number;
  /** Pre-formatted return_usd as USD with cents and thousands separators: "$1,612.90" / "$12,500.00". The GROSS return (the stake included), so it carries no sign. Convenience only; return_usd is the source value. Omitted when return_usd is. */
  payout_display?: string;
  /** Pre-formatted PROFIT on the stake -- return_usd minus stake_usd, i.e. the payout net of what you put in -- as a signed USD string: "+$612.90". Distinct from payout_display, which is gross. Omitted when return_usd is. */
  profit_display?: string;
  /** Backend-owned CLV capture disposition. "pending" means no capture decision exists yet; terminal provider or quality statuses remain distinguishable. The raw close price and timestamp are never serialized. */
  clv_status?: string;
  /** Backend-owned CLV evidence basis. `frozen_displayed_entry` uses the persisted displayed entry. `historical_provider_entry` uses a known-CLOB point at or before publication. `historical_provider_price_match` requires the latest point in the prior hour to match. `historical_provider_nearby_price_match` requires a matching point within five minutes before publication. Source-null bases preserve unknown original provenance. */
  clv_basis?: string;
  /** Closing-line value toward the backed side, computed as (close / entry - 1) * 100. The basis-specific provider p entry must match the stored display; historical_provider_price_match also requires source provenance to remain null and its latest entry to be within the one-hour window at or before publication. Every basis requires a later quality-checked p close from the same series in the bounded post-entry, pre-kickoff window. Omitted when not measured. */
  clv_pct?: number;
  /** Backend-formatted signed CLV percentage, present exactly when clv_pct is present. */
  clv_display?: string;
  /** Backend-owned CLV formula text with the entry probability, close probability, and rounded result. Provider timestamps remain private. */
  clv_explanation?: string;
  /** Net return for the pick in stake units (return_usd / stake_usd - 1); one unit is one stake_usd stake, and the figure is the same under any stake size. Omitted when the outcome is not valued. */
  unit_score?: number;
  /** Backend-formatted signed unit score, present exactly when unit_score is present. */
  unit_score_display?: string;
  /** Recorded sharp-money share as a 0..1 fraction when available. This is not a winning probability. */
  sharp_pct?: number;
  /** Recorded market-implied probability as a 0..1 fraction when available. */
  market_pct?: number;
  /** Optional recorded specialist facts. These describe the trader and do not disclose selection decisions. Present only on a full response when available. */
  qualifying_expert?: {
    /** Trader wallet address. */
    address: string;
    /** Provider display name, or null for an unnamed wallet. */
    name: string | null;
    /** Recorded trader grade. Public V1 preserves its S/A compatibility projection. */
    grade: string | null;
    /** The canonical sport bucket the win rate was measured over (for example Basketball). Can be BROADER than the pick's display_category, which names an exact league such as NBA — label the rate with this field, never with display_category. */
    canonical_category: string;
    /** Share of the trader’s resolved markets in canonical_category with positive realized P&L, as a 0..1 fraction. Null when not measured. This is a trader statistic, not the pick’s probability of winning. */
    win_rate: number | null;
    /** Number of resolved markets behind win_rate; null when not measured. */
    n_resolved: number | null;
    /** Recorded Polymarket position value on the backed outcome, in USD. It can change after this snapshot. */
    position_usd: number;
    /** Recorded position value on the other outcome of this market, in USD. Omitted when not recorded; zero is a measured value. */
    opposite_position_usd?: number;
    /** Timestamp of the recorded trader statistics. */
    stats_computed_at: string;
  };
  /** Public V1 S/A wallet count on the backed side, equal to sharp_wallet_count. */
  traders?: number;
  /** Recorded backed-side sharp-money value in USD when available. */
  backed_sharp_usd?: number;
  /** Bounded S/A holder display projection. Historical rows retain their recorded display shape. */
  holders?: PickHolder[];
  /** Optional complete holder display roster. Each entry carries ordinary trader and recorded position facts. */
  display_holders?: PickHolder[];
  /** S/A holder count for the public V1 compatibility projection. display_holders can include additional grades. */
  holder_count?: number;
  /** Optional editorial note attached to the pick. */
  editorial_note?: string;
  /** Required truthful thesis. With at least one profitable-wallet holder: Profitable wallets hold {pick_outcome_label}[, led by a grade-{top_grade} trader]. Without holder backing: 0xInsider's Pick of the Day is {pick_outcome_label}. Wallet counts are not appended. */
  thesis?: string;
  /** Canonical web market URL. */
  market_url?: string;
  /** Where this pick's outbound Polymarket link lands: Polymarket's own redirect answer for `/event/<event_slug>`, carrying the referral tag. Omitted until that redirect has been resolved; link to the event page instead when it is absent. */
  polymarket_url?: string;
  /** The canonical /event game-page slug (one neutral page per game); omitted when the game has no neutral event page. */
  event_slug?: string;
  /** Backend-resolved /event destination slug for the source market. Omitted outside full responses; null is an authoritative no-link decision. */
  event_link_slug?: string | null;
  /** Provider-first sports context for the pick's market (team logos, league branding, live score). Full-state only; omitted when the pick is not a team-sports market. */
  sports_context?: PickSportsContext;
  /** Risk disclaimer shown with every pick. */
  disclaimer?: string;
  /** Published same-day picks whose holder proof is not readable yet, ordered by pick_rank. Additive and optional: present only while at least one such pick exists. While present, `picks` carries only the proof-readable picks and `pick_count` counts them. Schedule the next read from the earliest retry_at instead of polling. The route returns 503 read_model_warming only when no published pick has readable proof. */
  proof_pending_picks?: ProofPendingPickSlot[];
  /** Optional full-response entry authorization. Missing or expired authorization cannot authorize an automated entry. */
  entry_authorization?: PotdEntryAuthorization;
  /** Stable pick row identity as decimal text. Never use a quality rank as identity. */
  pick_id?: string;
  /** Compatibility release slot. No quality claim; historic scheduling order is retained. */
  publication_order?: number;
  /** Viewer-independent free selection designation. New rows store it explicitly; historic null storage uses the original free slot. */
  is_free_selection?: boolean;
  /** Replacement predecessor stable id; null when no lineage is recorded. */
  supersedes_pick_id: string | null;
};

export type PickOfTheDayArchive = {
  /** Every published Pick of the Day, newest first by pick_date and then pick_rank within each product day. */
  picks: PickOfTheDayArchiveEntry[];
  /** One entry per product day that has a published pick, newest first, in the same order as picks. Each carries that day's net units, accumulated in the same backend pass and behind the same visibility gate as hit_rate.unit_score, so both cover the same population of picks. Re-adding the day totals reproduces hit_rate.unit_score to display precision rather than bit-for-bit, since that re-associates the floating-point sum. */
  days: PickOfTheDayArchiveDay[];
  hit_rate: PickOfTheDayHitRate;
};

export type PickOfTheDayArchiveDay = {
  /** The product day (YYYY-MM-DD). */
  date: string;
  /** Published picks on the day: wins + losses + void + pending. */
  picks: number;
  /** Picks on the day that resolved as a win, counted by the same pass as hit_rate.wins, so the day entries sum to the headline record. */
  wins: number;
  /** Picks on the day that resolved as a loss, counted by the same pass as hit_rate.losses. */
  losses: number;
  /** Picks on the day that resolved void (stake refunded). */
  void: number;
  /** Picks on the day not yet resolved. A day whose picks are all pending is a real 0-0 day with pending > 0, not a missing record. */
  pending: number;
  /** Net units over the day's visible, valued, decided (win/loss) picks: the same population staked_usd runs over. Omitted when the day has not scored -- every pick still pending, every pick void, or a price-gated current row -- which is not the same as a real 0.0 day. */
  unit_score?: number;
  /** unit_score pre-formatted as signed units to two decimals (for example +1.24u or -2.00u), by the same formatter the per-pick unit_score_display and hit_rate.unit_score_display use. Present exactly when unit_score is; unit_score is the source value. */
  unit_score_display?: string;
  /** win when every decided pick on the day won, loss when every one lost, over at least three decided (win or loss) picks with nothing pending. Omitted for every other day. A void is not a result: it neither lifts a day over the floor nor spoils a sweep. */
  sweep?: "win" | "loss";
};

export type PickOfTheDayArchiveEntry = {
  /** The pick's local publication date (YYYY-MM-DD). */
  pick_date: string;
  /**
   * Deprecated compatibility daily release slot; use pick_id for identity and publication_order for scheduling.
   * @deprecated
   */
  pick_rank?: number;
  /** When this pick became public (RFC3339 UTC). pick_date above is the America/New_York product day, not an instant, so read this whenever you need a real time: reading the bare date as UTC midnight places it hours before the earliest instant a pick can drop (07:00 UTC on that date). A day's last pick can drop at 23:00 ET, which is the following UTC date. Omitted (not null) when the instant is unknown; additive and optional for mixed-version client compatibility. */
  published_at?: string;
  /** Human-readable matchup (e.g. "Portugal vs. Uzbekistan"). */
  matchup: string;
  /** Frozen canonical calibration/report bucket (e.g. "Basketball", "MMA", or "Soccer"). Existing semantics are unchanged; presentation consumers should prefer display_category when present. */
  category: string;
  /** Frozen public presentation category: the competition the Polymarket event belongs to. A curated label comes first -- an official league (e.g. "WNBA" or "UFC"), the esports title (e.g. "CS2", "LoL", "Dota 2" or "Valorant"), or a soccer competition (e.g. "LaLiga", "Premier League", "Serie A" or "UEFA Champions League"); any other competition carries the provider's own competition name without its season year (e.g. "UEFA Nations League", "ATP" or "Wimbledon"). It equals category only when the provider names no competition. An esports pick keeps the pooled "Esports" bucket in category, so a per-title label never implies a per-title measured cohort. Additive and optional for mixed-version client compatibility. */
  display_category?: string;
  /** Provider (Polymarket Gamma) market thumbnail URL (markets.image); omitted (not null) when the market has no image. Public regardless of the backed-side gate, so present for pending rows too. */
  image_url?: string;
  /** The backed side's outcome label. Omitted for a still-pending pick when the request is not from an authenticated Pro key. */
  pick_outcome_label?: string;
  /** Best public V1-compatible S/A sharp-money grade on the backed side; a current B-only grade is omitted by the stable V1 adapter, while historical rows retain their frozen policy's grade. Omitted when no sharp-money wallet backs the pick, when a pending legacy proof has not yet upgraded, or when the stored holder policy is unknown-future or structurally invalid. Resolved legacy history remains supported. */
  top_grade?: string;
  /** Settlement outcome of the backed side; 'pending' until the market resolves. */
  outcome: "pending" | "win" | "loss" | "void";
  /** Pre-formatted settlement status for display: "Win" / "Loss" / "Void" / "Pending" -- the outcome enum above as a label, from the same formatter the pick payload's outcome_display uses. Convenience only; outcome is the source value. */
  outcome_display?: string;
  /** When outcome was LAST written to a settled value (RFC3339 UTC), the same instant the commitment ledger publishes. It moves with a corrected market re-mapping an already-settled pick. Omitted (not null) for a pending pick and for a pick that settled before the instant was recorded, so absence means the instant is unknown, never that the pick is unsettled -- outcome answers that. Additive and optional for mixed-version client compatibility. */
  resolved_at?: string;
  /** The flat stake this row was valued at, in USD: 1000 since 2026-09-22 (100 before). Every row of the record is valued at the current stake, including picks published before the change. Present exactly when return_usd is. */
  stake_usd?: number;
  /** Gross return of stake_usd on this resolved pick: a win returns stake_usd / backed_price, a loss returns 0, a void refunds stake_usd. A loss always returns 0 (the whole stake is lost regardless of price). The operand is published beside it as backed_price on exactly the same rows, so the entry never has to be recovered by inverting this number. Omitted (not null) only for a still-pending pick or a resolved WIN with no frozen price (a win's payout needs the price); mirrors the backend skip-when-absent behavior and the route-client optional (non-nullable) schema. */
  return_usd?: number;
  /** The same return on a literal $100 (a win returns 100 / backed_price, a loss 0, a void 100), kept for compatibility: the field predates stake_usd and its name promises the $100 basis. Present exactly when return_usd is. */
  return_per_100?: number;
  /** Pre-formatted return_usd as USD with cents: "$2,000.00". Present exactly when return_usd is -- it is formatted from that already-gated value -- so it is omitted for a still-pending pick, an unpriced win, and any pick whose backed side is withheld. Convenience only; return_usd is the source value. */
  payout_display?: string;
  /** Frozen price of the backed side (0..1) that return_usd and return_per_100 were computed from: on a win, stake_usd / backed_price equals return_usd. It is the Polymarket CLOB order book midpoint at release, frozen write-once at publication, not an executed fill: a buyer lifts the ask, so a subscriber's own entry is usually a little worse than this price. Present exactly when return_usd is, so it is omitted for a still-pending pick, an unpriced win, and any pick whose backed side is withheld. */
  backed_price?: number;
  /** Closing-line value toward the backed side, computed as (close / entry - 1) * 100. Omitted when the row is gated, ineligible, or not measured. */
  clv_pct?: number;
  /** Backend-formatted signed CLV percentage, present exactly when clv_pct is present. */
  clv_display?: string;
  /** Entry operand of clv_pct: the frozen pick probability the close is compared against. It equals backed_price, which CLV eligibility requires. Present exactly when clv_pct is. */
  clv_entry_price?: number;
  /** Close operand of clv_pct: the last valid Polymarket probability before the close bound (kickoff, or the first instant the live feed reported the game in progress when that came earlier). Present exactly when clv_pct is; the close timestamp stays private. */
  clv_close_price?: number;
  /** Whether CLV applies. A visible resolved pick published after kickoff is not_applicable. */
  clv_applicability?: "applicable" | "not_applicable";
  /** Backend-owned CLV text. A measured row names the entry, then the close, then the formula (close / entry - 1) x 100 and its rounded result; otherwise it gives the reason CLV does not apply or is unavailable. */
  clv_explanation?: string;
  /** Exact backend CLV capture disposition for this visible row. Pending and terminal provider or quality statuses are distinguishable; capture timestamps are never serialized, while a measured row's entry and close prices are published as clv_entry_price and clv_close_price. */
  clv_status?: string;
  /** Backend-owned CLV evidence basis. Source-null price-match bases preserve unknown original provenance. `historical_provider_nearby_price_match` requires a matching Polymarket point within five minutes before publication. */
  clv_basis?: string;
  /** Net return for this pick in stake units (return_usd / stake_usd - 1), where one unit is one stake_usd stake; the same figure under any stake size. Omitted when the backed side is withheld or the pick is not valued. */
  unit_score?: number;
  /** Backend-formatted signed unit score, present exactly when unit_score is present. */
  unit_score_display?: string;
  /** Stable pick row identity as decimal text. Never use a quality rank as identity. */
  pick_id: string;
  /** Compatibility release slot. No quality claim; historic scheduling order is retained. */
  publication_order: number;
  /** Viewer-independent free selection designation. New rows store it explicitly; historic null storage uses the original free slot. */
  is_free_selection: boolean;
  /** Replacement predecessor stable id; null when no lineage is recorded. */
  supersedes_pick_id: string | null;
};

/** Select using the entry commitment_version, never implicit payload shape. All historic v1 hashes remain unchanged. */
export type PickOfTheDayCommitmentPayload = PickOfTheDayCommitmentPayloadV1 | PickOfTheDayCommitmentPayloadV2;

/** The frozen identity of the pick, exactly as the hash was taken over it. Served byte for byte as it was hashed -- keys sorted by UTF-8 byte value, no insignificant whitespace -- so a verifier concatenates and hashes with nothing to reconstruct. Property order below is the wire order. The outcome is deliberately NOT part of it: surviving a corrected outcome unchanged is the case the commitment exists for. Worked example: {"backed_price":"0.545000","condition_id":"0xabc","kickoff":"2026-09-20T23:05:00Z","pick_date":"2026-09-20","pick_outcome_index":1,"pick_outcome_label":"Lakers","pick_rank":1,"platform":"polymarket"} with the nonce 000102030405060708090a0b0c0d0e0f101112131415161718191a1b1c1d1e1f hashes to 44d18fa5e2aa3a2bf3c971dcc9317c8ccbdfd5480a4773b6d8ffd5fbeeea84dc. */
export type PickOfTheDayCommitmentPayloadV1 = {
  /** Frozen pre-game price of the backed side, 0..1, as the plain decimal text of the stored NUMERIC at full stored precision, trailing zeros included. A string, never a number: a float round-trip would change the bytes and break the hash. Deliberately not normalized -- 0.545000 stays "0.545000". */
  backed_price: string;
  /** Provider condition id of the backed market. */
  condition_id: string;
  /** Frozen provider kickoff, whole seconds, UTC, literal Z. Fixed precision, never a shortest-lossless rendering. */
  kickoff: string;
  /** ET product day (YYYY-MM-DD). */
  pick_date: string;
  /** Index of the backed outcome within the market. */
  pick_outcome_index: 0 | 1;
  /** Frozen display label of the backed outcome. */
  pick_outcome_label: string;
  /** 1-based daily slot. */
  pick_rank: number;
  /** Provider platform. Always polymarket. */
  platform: "polymarket";
};

/** Version 2 rank-free canonical payload: sorted nine keys, unchanged string escaping, exact decimal text and whole-second UTC kickoff. pick_id is decimal text; version is JSON integer 2. */
export type PickOfTheDayCommitmentPayloadV2 = {
  /** Frozen pre-game price of the backed side, 0..1, as the plain decimal text of the stored NUMERIC at full stored precision, trailing zeros included. A string, never a number: a float round-trip would change the bytes and break the hash. Deliberately not normalized -- 0.545000 stays "0.545000". */
  backed_price: string;
  /** Provider condition id of the backed market. */
  condition_id: string;
  /** Frozen provider kickoff, whole seconds, UTC, literal Z. Fixed precision, never a shortest-lossless rendering. */
  kickoff: string;
  /** ET product day (YYYY-MM-DD). */
  pick_date: string;
  /** Index of the backed outcome within the market. */
  pick_outcome_index: 0 | 1;
  /** Frozen display label of the backed outcome. */
  pick_outcome_label: string;
  /** Provider platform. Always polymarket. */
  platform: "polymarket";
  /** Stable pick row identity as decimal text. Never use a quality rank as identity. */
  pick_id: string;
  version: 2;
};

export type PickOfTheDayHitRate = {
  /** Number of decided picks that won. */
  wins: number;
  /** Number of decided picks that lost. */
  losses: number;
  /** Number of decided picks (wins + losses); excludes void and pending. */
  decided: number;
  /** Rolling hit rate as a percentage (wins / decided * 100, to 1 decimal); 0 when none are decided. */
  pct: number;
  /** Number of picks that resolved void (excluded from the hit rate). */
  void: number;
  /** Number of picks still pending resolution (excluded from the hit rate). */
  pending: number;
  /** The flat stake every money figure here assumes, in USD: 1000 since 2026-09-22 (100 before). Always present. */
  stake_usd?: number;
  /** Cumulative profit (USD) of a stake_usd-per-pick strategy over visible valued decided picks: a priced win pays stake_usd/backed_price - stake_usd, every visible loss pays -stake_usd independent of price, and a void pays 0. An unpriced visible win and a current non-Insider row whose price is gated remain in wins/losses but are excluded from price-derived totals. */
  net_profit_usd: number;
  /** Total staked (USD) = stake_usd * count of visible valued decided picks: every visible loss plus every priced win. Void, unpriced wins, and current non-Insider rows whose price is gated are excluded. */
  staked_usd: number;
  /** Return on the staked amount as a percentage (net_profit_usd / staked_usd * 100, to 1 decimal); 0 when nothing is staked. */
  roi_pct: number;
  /** Pre-formatted net profit for display, e.g. "+$100" / "-$40". Whole dollars, signed, round-then-signed so a rounds-to-zero record reads "+$0" (never "-$0"). Convenience only; net_profit_usd is the source value. */
  net_profit_display: string;
  /** Pre-formatted ROI for display, e.g. "+8.3%" / "-20.0%". One decimal, signed, round-then-signed so a rounds-to-zero record reads "+0.0%" (never "-0.0%"). Convenience only; roi_pct is the source value. */
  roi_display: string;
  /** Pre-formatted win rate for display, e.g. "92.3%". One decimal, unsigned. Convenience only; pct is the source value. */
  win_rate_display: string;
  /** Cumulative net return in stake units over the same valued win/loss population as net_profit_usd. */
  unit_score?: number;
  /** Backend-formatted signed cumulative unit score, for example "+1.25u". Omitted when no valued settled pick contributes to the aggregate. */
  unit_score_display?: string;
  /** Visible resolved archive rows with no CLV capture disposition yet. */
  clv_pending: number;
  /** Visible resolved archive rows with a terminal non-measured CLV disposition. */
  clv_unavailable: number;
  /** Aggregate CLV state. Counts remain available for mixed measured/pending/unavailable populations. */
  clv_state: "measured" | "pending" | "unavailable" | "not_applicable" | "none";
  /** Visible resolved archive rows with valid basis-specific CLV entry evidence. Known-source bases require CLOB provenance; historical_provider_price_match instead requires source provenance to remain null and the latest provider p entry in the one-hour window at or before publication to match the stored display. */
  clv_eligible: number;
  /** Every visible resolved archive row, including post-kickoff picks. A price-gated current row is excluded until its backed side becomes visible. */
  clv_total: number;
  /** Eligible resolved public rows with a measured Polymarket CLOB close. */
  clv_measured: number;
  /** Visible resolved rows published before kickoff. This is the CLV coverage denominator. */
  clv_applicable: number;
  /** Visible resolved rows published after kickoff. These rows remain public but do not enter coverage. */
  clv_not_applicable: number;
  /** Measured divided by clv_applicable as a percentage. Omitted when clv_applicable is zero. */
  clv_coverage_pct?: number;
  /** Backend-formatted measured/clv_applicable coverage percentage. */
  clv_coverage_display?: string;
  /** Backend-owned coverage count text, including the excluded post-kickoff count. */
  clv_coverage_explanation?: string;
  /** Arithmetic mean of per-pick ratio CLV, (close / entry - 1) * 100. A cheap entry weighs more here than a favorite, so the headline average is clv_avg_pp; this field is kept for continuity. Suppressed until at least five measured rows exist. */
  clv_avg_pct?: number;
  /** Backend-formatted signed average CLV percentage, present when clv_avg_pct is present. */
  clv_avg_display?: string;
  /** Arithmetic mean of the measured closing-line move in percentage points, (close - entry) * 100, so every pick counts on the same scale. The headline CLV average. Covers the same measured rows as clv_avg_pct and is suppressed under the same five-row floor. */
  clv_avg_pp?: number;
  /** Backend-formatted signed average in percentage points, for example "+0.4 pp"; a value that rounds to zero reads "0.0 pp". Present when clv_avg_pp is present. */
  clv_avg_pp_display?: string;
  /** Measured public rows where close is strictly greater than entry. */
  clv_beats_close: number;
  /** Measured public rows where close exactly equals entry. */
  clv_ties: number;
  /** Cumulative track-record series, one point per decided (win/loss) pick in ascending pick_date order (void and pending add no point). A non-valued decided row carries cumulative profit forward while advancing hit rate. The last point's net_profit_usd and hit_rate_pct equal the headline net_profit_usd and pct by construction. Empty when nothing is decided. */
  series?: {
    /** The decided pick's publish date (YYYY-MM-DD). */
    date: string;
    /** Running cumulative stake_usd-per-pick profit (USD) through this pick; valued losses and priced wins are booked, while a non-valued decided row carries profit forward unchanged. */
    net_profit_usd: number;
    /** Running rolling hit rate (wins / decided * 100, to 1 decimal) through this pick. */
    hit_rate_pct: number;
  }[];
};

/** The commitment ledger: every published pick, ascending, in the state its commitment is actually in. The counts are derived from entries in the same pass that builds it. */
export type PickOfTheDayLedger = {
  /** One entry per published (pick_date, pick_rank), ascending by pick_date then pick_rank. */
  entries: PickOfTheDayLedgerEntry[];
  /** Number of entries, all states included. */
  entry_count: number;
  /** Entries committed to and not yet settled. */
  sealed_count: number;
  /** Entries committed to and verifiable now. */
  opened_count: number;
  /** Entries carrying no commitment, so provable by nothing: the honest size of the unprovable part of the record. It only stops growing; no pick is ever retro-sealed. */
  uncommitted_count: number;
};

/** One ledger entry. Read `state` to know which shape you have; the three are disjoint. */
export type PickOfTheDayLedgerEntry = PickOfTheDayLedgerSealedEntry | PickOfTheDayLedgerOpenedEntry | PickOfTheDayLedgerUncommittedEntry;

/** A settled pick whose commitment is open: the nonce plus the exact payload the hash was taken over. Concatenate the payload bytes as received with the decoded nonce and sha256 them to reproduce commitment_hash. */
export type PickOfTheDayLedgerOpenedEntry = {
  state: "opened";
  /** ET product day the pick belongs to (YYYY-MM-DD). */
  pick_date: string;
  /**
   * Deprecated compatibility daily release slot; use pick_id for identity and publication_order for scheduling.
   * @deprecated
   */
  pick_rank: number;
  /** sha256(canonical_json(payload) || nonce), lowercase hex, no 0x prefix. Publishable the moment the pick releases: without the nonce it is not invertible. */
  commitment_hash: string;
  /** The 32-byte nonce the hash was taken over, lowercase hex, no 0x prefix. Secret while the pick is live: a pick payload is low entropy, so a published nonce on a live pick would hand out the backed side. */
  commitment_nonce: string;
  /** The construction the hash was taken with, stated in the response so a verifier never has to guess the serialization. */
  commitment_algo: "sha256(canonical_json(payload)||nonce)";
  /** When the hash was frozen. Always strictly before kickoff: a pick that reaches kickoff unsealed stays unsealed forever, because a seal written after the game started would be a backdated proof. */
  sealed_at: string;
  /** When outcome was LAST written to a settled value, or null when that instant is unknown. It moves with a corrected market re-mapping an already-settled pick, while commitment_hash stays untouched -- which is how a mirror that keeps history sees a correction. */
  resolved_at: string | null;
  /** The frozen provider kickoff in the canonical payload form: whole seconds, UTC, literal Z. This exact string reappears inside payload.kickoff when the pick opens. */
  kickoff: string;
  payload: PickOfTheDayCommitmentPayload;
  /** How the pick settled. Never pending: a pending pick is a sealed entry. */
  outcome: "win" | "loss" | "void";
  /** Frozen matchup, for a reader. */
  matchup: string;
  /** Frozen canonical sport bucket used for selection calibration (Basketball, MMA), not the exact public league identity; the archive owns that. */
  category: string;
  /** The pick's public page. */
  permalink: string;
  /** Stable pick row identity as decimal text. Never use a quality rank as identity. */
  pick_id: string;
  /** Compatibility release slot. No quality claim; historic scheduling order is retained. */
  publication_order: number;
  /** Viewer-independent free selection designation. New rows store it explicitly; historic null storage uses the original free slot. */
  is_free_selection: boolean;
  /** Replacement predecessor stable id; null when no lineage is recorded. */
  supersedes_pick_id: string | null;
  /** Explicit proof provenance: 1 retains historic eight-field canonical JSON; 2 binds stable pick_id and version without pick_rank. */
  commitment_version: 1 | 2;
};

/** A published pick that has not settled. Carries the commitment and nothing that states a side or a price: no nonce, no payload, no outcome. Publishable the instant the pick releases. */
export type PickOfTheDayLedgerSealedEntry = {
  state: "sealed";
  /** ET product day the pick belongs to (YYYY-MM-DD). */
  pick_date: string;
  /**
   * Deprecated compatibility daily release slot; use pick_id for identity and publication_order for scheduling.
   * @deprecated
   */
  pick_rank: number;
  /** sha256(canonical_json(payload) || nonce), lowercase hex, no 0x prefix. Publishable the moment the pick releases: without the nonce it is not invertible. */
  commitment_hash: string;
  /** The construction the hash was taken with, stated in the response so a verifier never has to guess the serialization. */
  commitment_algo: "sha256(canonical_json(payload)||nonce)";
  /** When the hash was frozen. Always strictly before kickoff: a pick that reaches kickoff unsealed stays unsealed forever, because a seal written after the game started would be a backdated proof. */
  sealed_at: string;
  /** The frozen provider kickoff in the canonical payload form: whole seconds, UTC, literal Z. This exact string reappears inside payload.kickoff when the pick opens. */
  kickoff: string;
  /** The pick's public page. */
  permalink: string;
  /** Stable pick row identity as decimal text. Never use a quality rank as identity. */
  pick_id: string;
  /** Compatibility release slot. No quality claim; historic scheduling order is retained. */
  publication_order: number;
  /** Viewer-independent free selection designation. New rows store it explicitly; historic null storage uses the original free slot. */
  is_free_selection: boolean;
  /** Replacement predecessor stable id; null when no lineage is recorded. */
  supersedes_pick_id: string | null;
  /** Explicit proof provenance: 1 retains historic eight-field canonical JSON; 2 binds stable pick_id and version without pick_rank. */
  commitment_version: 1 | 2;
};

/** A published pick with no commitment: it predates the scheme, or it reached kickoff unsealed. Nothing here is evidence of WHEN the pick was made. It is emitted rather than skipped, because a ledger with holes where the unprovable picks were would silently flatter the record. Once the pick settles, payload names its market, side and price, so the outcome can still be checked against the market's own resolution. */
export type PickOfTheDayLedgerUncommittedEntry = {
  state: "uncommitted";
  /** ET product day the pick belongs to (YYYY-MM-DD). */
  pick_date: string;
  /**
   * Deprecated compatibility daily release slot; use pick_id for identity and publication_order for scheduling.
   * @deprecated
   */
  pick_rank: number;
  /** Always true: this pick has no commitment and never will. */
  pre_commitment: true;
  /** How the pick settled, or pending. */
  outcome: "pending" | "win" | "loss" | "void";
  /** Frozen matchup, for a reader. */
  matchup: string;
  /** Frozen canonical sport bucket used for selection calibration (Basketball, MMA), not the exact public league identity; the archive owns that. */
  category: string;
  /** When outcome was LAST written to a settled value, or null when that instant is unknown. It moves with a corrected market re-mapping an already-settled pick, while commitment_hash stays untouched -- which is how a mirror that keeps history sees a correction. */
  resolved_at: string | null;
  /** The pick's market, side and price once it has settled; null while it is pending, and null for a settled pick whose stored row lacks one of these columns. Not hashed: nothing was committed over these values, which is what pre_commitment: true says. */
  payload: PickOfTheDayUncommittedPayload | null;
  /** The pick's public page. */
  permalink: string;
  /** Stable pick row identity as decimal text. Never use a quality rank as identity. */
  pick_id: string;
  /** Compatibility release slot. No quality claim; historic scheduling order is retained. */
  publication_order: number;
  /** Viewer-independent free selection designation. New rows store it explicitly; historic null storage uses the original free slot. */
  is_free_selection: boolean;
  /** Replacement predecessor stable id; null when no lineage is recorded. */
  supersedes_pick_id: string | null;
};

/** A settled uncommitted pick's market, side and price. The same eight fields as PickOfTheDayCommitmentPayload, in the same key order, so a settled pick's side and price sit under payload whatever the entry's state. It is NOT a commitment: no hash was taken over it before the game, and it proves nothing about when the pick was made. */
export type PickOfTheDayUncommittedPayload = {
  /** Frozen pre-game price of the backed side, 0..1, as the plain decimal text of the stored NUMERIC at full stored precision, trailing zeros included -- rendered exactly as the commitment payload renders it. */
  backed_price: string;
  /** Provider condition id of the backed market. */
  condition_id: string;
  /** Frozen provider kickoff, UTC, literal Z; null when no kickoff was frozen. Whole seconds render exactly as the commitment payload does; a sub-second instant keeps its fraction rather than being truncated, since nothing here is hashed. */
  kickoff: string | null;
  /** ET product day (YYYY-MM-DD). */
  pick_date: string;
  /** Index of the backed outcome within the market. */
  pick_outcome_index: 0 | 1;
  /** Frozen display label of the backed outcome. */
  pick_outcome_label: string;
  /** 1-based daily slot. */
  pick_rank: number;
  /** Provider platform. Always polymarket. */
  platform: "polymarket";
};

/** Provider-first sports context for a Pick of the Day market: team crests, league branding, and live score. Team logos and league logo are provider-owned (Polymarket /teams crests for clubs, country flags for national teams and tennis players); no local derivation. */
export type PickSportsContext = {
  /** League or competition display name (e.g. "Premier League"). */
  league_name: string | null;
  /** Provider-owned event taxonomy from Gamma eventMetadata, joined in league · serie · tournament order with blanks and case-insensitive duplicates removed. Separate from league_name; omitted when the provider does not supply the metadata. */
  competition_label?: string;
  /** League logo URL (provider-owned). */
  league_logo: string | null;
  /** The team mapped to the market's YES outcome, or the parent-event home/first team when event_matchup is true. */
  yes_team: PickSportsTeam;
  /** The team mapped to the market's NO outcome, or the parent-event away/second team when event_matchup is true. */
  no_team: PickSportsTeam;
  /** Provider game identifier (Polymarket Gamma gameId); omitted when the provider supplies none. */
  game_id?: number;
  /** Always present. True when the two teams are the parent-event match identity for a teamless binary leg (e.g. a draw, totals, or prop market), not the market's own outcomes. */
  event_matchup: boolean;
  /** Present only alongside event_matchup: the event team the binary leg is about (provider group_item_title matched to a matchup team, e.g. Belgium for "Will Belgium win?"), i.e. the winner on a Yes resolution. Omitted for teamless legs (draw, totals, prop). */
  event_subject_team?: PickSportsTeam;
  /** The two teams as a single whole-game label, joined "<home> – <away>" (en-dash) in provider display order (e.g. "Portugal – Uzbekistan"). Composed server-side from the provider team names (no title/slug parsing). Present when both teams resolve a name; omitted for single-subject, teamless, or non-two-team contexts. */
  matchup_title?: string;
};

/** A single sports team or competitor in a Pick of the Day market's sports context. Identity and score fields are provider-owned and nullable. The structured score fields (`sets`, `format`, `sets_won`) and the tennis fields (`headshot`, `headshot_revision`, `tour`) are backend-owned and are OMITTED rather than null when they do not apply, so a consumer must treat an absent key and a null the same way. */
export type PickSportsTeam = {
  /** Team display label as it appears on the market outcome (e.g. "Portugal"). */
  label: string | null;
  /** Abbreviated team label (e.g. "POR"). */
  short_label: string | null;
  /** Full team or competitor name (e.g. "Portugal national football team"). */
  full_name: string | null;
  /** Provider team identifier (Polymarket /teams id). */
  provider_id: number | null;
  /** Team crest or flag URL. Provider-owned for most teams (Polymarket /teams crest for clubs, country flag for national teams and tennis players). A club with a vendored crest carries it instead, served same-origin as a relative path (`/api/sports/team-logos/{league}/{abbr}.svg?v=<content hash>` or `.png`, resolve it against this server): every NFL and WNBA team, whose provider asset is a text tile, and the soccer clubs whose provider asset is an empty object. */
  logo: string | null;
  /** True when the team mark is dark enough to disappear on a dark background, measured from the artwork by the teams sync. Render a dark mark on a light plate. Always sent; false until the artwork has been measured. */
  logo_mark_dark: boolean;
  /** Team brand color as a hex string (provider-owned). */
  color: string | null;
  /** Win-loss record as a display string (e.g. "12-4"). */
  record: string | null;
  /** Live or final score as a display string when the game is in play or settled. */
  score: string | null;
  /** Tennis player headshot URL, served same-origin. Present only for a tennis competitor the headshot resolver matched; absent for team sports and for unmatched players, where `logo` stays the fallback. */
  headshot?: string;
  /** Optional monotonic photo revision for this tennis player, independent of the sports score revision. Legacy stored photos start at zero. Successful new or changed image bytes advance it; source checks and attribution changes do not. Compare only for the same tour and provider_id: a higher revision replaces the portrait, an equal revision may fill a missing portrait, and a lower revision must not replace a newer one. Absent when no photo resolved. */
  headshot_revision?: number;
  /** Tennis tour this competitor belongs to. Present for every tennis entry whether or not `headshot` resolved, so a consumer can tell a tennis player with no photo from a non-tennis team. Absent for every other sport. Only `atp` and `wta` name a gender; the ITF World Tennis Tour runs men's and women's events and the provider does not say which, so `itf` means tennis with gender unknown. */
  tour?: "atp" | "wta" | "itf";
  /** Per-set score cells for this side, in set order. Backend-owned: render these rather than parsing `score`. Omitted entirely when the provider score is not a structured multi-set match or could not be parsed, so an absent array and an empty one carry the same meaning. */
  sets?: ScoreCell[];
  format?: ScoreFormat;
  /** Completed sets won by this side. Present only when both sides expose the same set columns, so a partially parsed scoreline reports no tally rather than a misleading one. */
  sets_won?: number;
};

export type PlatformCapabilities = {
  grade: PlatformCapabilityStatus;
  pnl: PlatformCapabilityStatus;
  strategy: PlatformCapabilityStatus;
  timeline: PlatformCapabilityStatus;
  /** The large-trade feed. Canonical key since #16304; whale_signal is its deprecated spelling, emitted beside it with the same value. */
  large_trades: PlatformCapabilityStatus;
  whale_signal: PlatformCapabilityStatus;
  suspicious_trades: PlatformCapabilityStatus;
  insider_radar: PlatformCapabilityStatus;
  market_snapshot: PlatformCapabilityStatus;
};

/** Every capability the API serves reports supported. The field names a per-capability status so a client can branch on coverage; no other value is emitted. */
export type PlatformCapabilityStatus = "supported";

export type Platforms = {
  platforms: {
    polymarket: PlatformCapabilities;
  };
};

export type Position = {
  /** Composite prefixed ID `pos_<wallet>:<condition_id>:<outcome_index>`. */
  id: string;
  /** Provider discriminator. Polymarket only. */
  platform: "polymarket";
  /** Lowercased proxy wallet address. */
  wallet: string;
  /** Binary outcome side. Non-binary positions are not surfaced on V1. */
  side: "YES" | "NO";
  /** The Polymarket CLOB token id (ERC1155 asset id, decimal string) for this outcome; null when unavailable (e.g. unsynced markets). */
  token_id: string | null;
  /** Live share count from the wallet_positions mirror. */
  shares: number;
  /** Volume-weighted entry price for this leg. */
  avg_price?: number;
  /** Current mark-to-market value in USD (always non-null on V1 — pre-reconcile rows are excluded). */
  current_value_usd: number;
  initial_value_usd?: number;
  /** Unrealized P&L for the open position (Polymarket `cashPnl`). */
  cash_pnl?: number;
  /** Closed-leg P&L rolled up (Polymarket `realizedPnl`). */
  realized_pnl?: number;
  /** Additive lossless source atoms for the display-safe position fields. Parse every `value` with decimal-safe arithmetic; never recover exact values from the numeric twins. */
  exact?: PositionExact;
  /** Max updated_at across mirror legs for this pair. */
  last_reconciled_at?: string;
  /** Backend-computed staleness bucket derived from last_reconciled_at. */
  freshness: "fresh" | "refreshing" | "stale" | "unknown";
  trader: {
    /** Prefixed ID (`trd_...`). */
    id: string;
    address: string;
    username?: string;
    grade?: "S" | "A" | "B" | "C" | "D" | "F";
    /** Percentage 0-100. */
    win_rate?: number;
    pnl?: number;
    markets?: number;
    wallet_age_days?: number;
    /** True when 0xinsider first recorded the wallet within the new-wallet threshold (30 days). This public V1 field is first-seen recency, not the wallet's on-chain age. */
    is_new_wallet: boolean;
  };
  market: {
    /** Prefixed ID (`mkt_...`). */
    id: string;
    condition_id: string;
    title: string;
    slug?: string;
    event_slug?: string;
    /** Provider-backed market_canonical category. */
    category?: string;
    /** Provider-reported outcome label (e.g. team name for sports). Separate from `side` because provider labels can diverge from the binary Yes/No axis. */
    outcome_label?: string;
    end_date?: string;
  };
};

/** Lossless position atoms from `wallet_positions`. `shares` and `current_value_usd` are required when this object is present; other source values are omitted when the mirror has no verified value. */
export type PositionExact = {
  shares: ExactDecimal;
  cost_basis_usd?: ExactDecimal;
  /** Exact derived price: `wallet_positions.cost_basis_usd / wallet_positions.shares`. */
  avg_price?: ExactDecimal;
  current_value_usd: ExactDecimal;
  initial_value_usd?: ExactDecimal;
  cash_pnl?: ExactDecimal;
  realized_pnl?: ExactDecimal;
};

export type PositionTimelineEvent = {
  /** Prefixed ID (pe_...). */
  id: string;
  /** ISO 8601 timestamp of the on-chain fill. */
  event_timestamp: string;
  /** From the taker's perspective. */
  action: "buy" | "sell";
  outcome_side: "yes" | "no";
  /** The Polymarket CLOB token id (ERC1155 asset id, decimal string) for this outcome; null when unavailable (e.g. unsynced markets). */
  token_id: string | null;
  /** Signed share delta (+ on buy, − on sell). */
  amount_delta: number;
  /** Fill price in USDC per share, in [0,1]. */
  price: number;
  /** Positive USDC notional of the fill. */
  usdc_notional: number;
  /** Polygon transaction hash of the fill. */
  tx_hash: string;
  /** Cumulative signed stored-fill amount for this outcome after this fill, including older pages. Stable across limits/cursors for unchanged source history. Excludes split, merge, redemption and neg-risk activity; not complete holdings. Incomplete fill history can also leave a negative amount. */
  running_amount: number;
  /** Cumulative buy-weighted average of stored fills for this outcome, including older pages; not provider current-position avgPrice. Sells do not change this value. 0 when no stored buys have occurred yet. */
  running_avg_price: number;
};

/** Returned entry permission bound to the named market, token and outcome. Honor max_entry_price and expires_at, and check a current executable order book for the actual stake. This snapshot does not guarantee current liquidity, execution or positive expected value. */
export type PotdEntryAuthorization = {
  version: 1;
  authorization_id: string;
  policy_version: 7;
  condition_id: string;
  token_id: string;
  outcome_index: 0 | 1;
  /** Canonical sport bucket, not display_category. */
  category: string;
  /** Exact provider parent event ID, or provider event ID when no parent exists. */
  canonical_event_id: string;
  /** Returned maximum entry price as an exact decimal string. Honor this bound; fees are excluded. This is not a fair probability. */
  max_entry_price: string;
  reference_best_ask: string;
  reference_book_hash: string;
  reference_book_at: string;
  issued_at: string;
  /** Authorization expiry. An expired authorization cannot authorize a new automated entry. */
  expires_at: string;
};

/** One ranked pre-game sports market where graded sharp money is piled on one side, with required-status shadow category evidence from partial forward-observed Polymarket fills. */
export type PreGameSide = {
  /** The side profitable wallets hold, as a provider-backed display label. Canonical spelling of piled_side (#16310), same value: when provider group context is unavailable it may remain a bare Yes/No/Over/Under, so do not use it alone as participant identity. */
  side: string | null;
  /** UTC time at which the snapshot that ranked this row was computed. Canonical spelling of signal_created_at (#16310), same value. */
  ranked_at: string;
  /** Recorded side backing score; higher values indicate stronger backing. */
  backing_score: number;
  /** Signed share of graded money on the side, (yes_usd - no_usd)/(yes_usd + no_usd) in [-1, 1] (side-yes positive, side-no negative). Canonical spelling of smart_score (#16309, #16310), same value. */
  side_share: number | null;
  /** Polymarket condition id. */
  condition_id: string;
  /**
   * UTC time at which the immutable signal snapshot was computed. Every row from one snapshot shares this value; it is not provider market creation time and is not rewritten at request time. Deprecated (#16310): `ranked_at` is the canonical spelling and carries the same value; this key stays on the wire.
   * @deprecated
   */
  signal_created_at: string;
  /** Polymarket CLOB token id (ERC1155 asset id, decimal string) for the PILED outcome; null when unavailable. */
  token_id: string | null;
  /** Canonical sport bucket (e.g. Basketball, Tennis); null when the raw category has no canonical mapping. */
  category: string | null;
  /** Raw provider category as stored (e.g. NBA, EPL). */
  raw_category: string | null;
  title: string | null;
  event_slug: string | null;
  /** Kickoff (UTC). In the future at SNAPSHOT time and within the requested horizon; because the response is served from a shared snapshot cached up to the ~180s TTL, a served kickoff can be up to ~180s in the past relative to the response time. Not a live guarantee that the game has not yet started. */
  game_start_time: string | null;
  /**
   * Nullable provider-backed piled-outcome display label. When provider group context is unavailable, it may remain a bare Yes/No/Over/Under; do not use it alone as participant identity. Deprecated (#16310): `side` is the canonical spelling and carries the same value; this key stays on the wire.
   * @deprecated
   */
  piled_side: string | null;
  /** Provider binary-column selector: 0 selects outcome_yes/token_id_yes; 1 selects outcome_no/token_id_no. It does not identify home/away or a participant. Use piled_side together with title/event context for display. */
  piled_outcome_index: number;
  /** Piled-side dollar concentration backed_usd / (yes_usd + no_usd), in (0.5, 1] for a real pile; null when there is no sharp USD. */
  sharp_pct: number | null;
  /** Raw piled-side sharp-money USD. */
  backed_sharp_usd: number;
  /** S-grade graded holders on the piled side. */
  s_count: number;
  /** A-grade graded holders on the piled side. */
  a_count: number;
  /** B-grade graded holders on the piled side. */
  b_count: number;
  /** Piled-side graded holder count (s_count + a_count + b_count). */
  graded_holders: number;
  /** Best grade present on the piled side; null when none. */
  top_grade: "S" | "A" | "B" | null;
  /**
   * Canonical sharp-money score (yes_usd - no_usd)/(yes_usd + no_usd) in [-1, 1] (piled-yes positive, piled-no negative). Deprecated (#16310): `side_share` is the canonical spelling and carries the same value; this key stays on the wire.
   * @deprecated
   */
  smart_score: number | null;
  /** Market volume (USD). */
  volume: number | null;
  /** Aggregate recent flow direction on the market; null when unavailable. */
  net_side: "BUY" | "SELL" | null;
  /**
   * Recorded conviction score; higher values indicate stronger conviction.
   * @deprecated
   */
  conviction_score: number;
  /** Piled-side graded holders read one-way: their fresh open legs across the signal game's markets (cross-market within the one game; moneyline+spread family only) all back the same team, or, when the market's holder scan was complete, Polymarket's currentValue shows no opposite leg on this market worth 10% of the backed leg and no fresh leg opposes it. Null when the directional read was not computed (no groupable game, no holder-level data on this ranking path, or the enrichment read failed) or classified nobody. */
  one_way_holder_count: number | null;
  /** Piled-side graded holders classified HEDGED across the game by fresh legs (they back two or more distinct teams). A wallet long both outcomes of this market is not one-way and not counted here. Null when the directional read was not computed or classified nobody. */
  hedged_holder_count: number | null;
  /** Piled-side graded USD held by one-way wallets (share-weighted allocation of backed_sharp_usd). Null when the directional read was not computed or classified nobody. */
  one_way_graded_usd: number | null;
  /** One-way fraction of the piled graded dollars, in [0, 1] -- the metric orthogonal to sharp_pct. Stale, unknown, hedged, and two-sided dollars dilute it toward zero (conservative). Null when the directional read was not computed or classified nobody. */
  directional_confidence: number | null;
  /** Recorded side ordering score; higher values sort first. */
  directional_rank_score: number;
  category_skill: PreGameSideCategorySkill;
  /** 1-based rank within the (min_grade-filtered) ranked result. */
  rank: number;
};

