export type Trader = {
  /** Prefixed ID (trd_...). */
  id: string;
  address: string;
  username?: string;
  grade?: "S" | "A" | "B" | "C" | "D" | "F";
  /** Hot-streak tier (trailing-7d cross-sectional percentile); a separate axis from the all-time grade. Omitted when there is no recent activity. */
  streak_tier?: "hot" | "rising" | "neutral" | "cooling" | "cold";
  score?: number;
  /** Optional forecast score on the documented display scale. Null when unavailable. */
  forecast_score?: number;
  /** Optional measured forecast context. Missing values remain unavailable rather than being inferred. */
  forecast_evidence?: number;
  rank?: number;
  pnl: {
    total?: number;
    /** For pnl.realized, expand=trust marks a matching native accounting snapshot as computed: native Polymarket realized P&L plus credited maker and taker rebates, with fees already included. The exact numeric value is truncated toward zero to cents before conversion to a JSON number. Without a matching native accounting snapshot, pnl.realized is omitted and its trust metadata is unavailable. Raw total P&L is never substituted for realized P&L. */
    realized?: number;
    unrealized?: number;
    /** DEPRECATED, never sent. The local pnl_7d rollup over-counted P&L (#5416 class) and is no longer emitted. Read the provider-native weekly window from GET /api/trader/{address}/profile-summary instead. */
    last_7d?: number;
    /** DEPRECATED, never sent. The local pnl_30d rollup over-counted P&L (#5416 class) and is no longer emitted. Read the provider-native monthly window from GET /api/trader/{address}/profile-summary instead. */
    last_30d?: number;
    /** Additive lossless counterpart. Omitted when the trusted native realized-P&L source is unavailable; existing numeric fields keep their display-safe v1 semantics. */
    exact?: TraderPnlExact;
  };
  stats: {
    markets_traded?: number;
    win_rate?: number;
    daily_win_rate?: number;
    /** Full-history both-sides USD cash volume from Polymarket user-volume. Omitted without a verified observation; never leaderboard shares. Its observation time is published as the volume group in data_quality and as trust.total_volume.freshness.as_of, both trader_usd_volume.observed_at; synced_at is a different clock and is never a substitute for it. */
    total_volume?: number;
    /** Additive lossless counterpart to `total_volume`. Omitted when the verified provider observation is unavailable. */
    exact?: TraderStatsExact;
  };
  strategy?: {
    /** Observed trading style identifier. New rows use two_sided, category_focused, high_activity, diversified, mixed, or unclassified. Historical identifiers remain readable during normal reclassification; style does not predict skill or intent. */
    strategy_type?: string;
    description?: string;
    confidence?: number;
  };
  /** Per-category rank context when expand=categories is requested. Values include available rank, category totals, performance and record counts; scaled_total_pnl is a legacy alias of total_pnl. Its measurement basis and update timing differ from the plain record returned by GET /api/v1/trader/{address}/categories, so the two need not agree. Use this for rank context and that route for the plain record. The inner key-set is intentionally unconstrained and may contain additional compatibility fields. */
  category_strengths?: Record<string, unknown>;
  /** Curated advanced risk/performance metrics (expand=quant_metrics or expand[]=quant_metrics). Omitted unless expanded and backed by a computed row strictly under six hours old; a missing row, NULL computed_at, or age of exactly six hours or more is stale and omitted. Provider-input changes may intentionally lag inside the bounded six-hour window. When present, all listed fields are present (each is a number or null); null means insufficient trade history and must not be treated as 0. The fixed field shape is unchanged. */
  quant_metrics?: {
    /** Trader smart score on a 0..100 display scale; higher is stronger. Null when unavailable. */
    smart_score: number | null;
    /** Copyability score, 0-100. Same base as smart_score minus penalties for traits that make a strategy hard to replicate: -20 if fewer than 50 markets traded, -15 if positions are highly concentrated, -15 if position sizing exceeds about 2x Kelly, -10 if the worst single-trade loss exceeds 30%, -10 if edge is inconsistent; result clamped to 0-100. Higher means easier to follow. null when insufficient history. */
    copy_score: number | null;
    /** Sharpe ratio over the trailing 30 days (risk-adjusted return; higher is better). Magnitude can be large for small samples. null when insufficient history. */
    sharpe_30d: number | null;
    /** Sharpe ratio over the trailing 7 days (risk-adjusted return; higher is better). null when insufficient history. */
    sharpe_7d: number | null;
    /** Gross profit divided by gross loss; greater than 1 is profitable. Capped at 1000 when there are effectively no losses. null when insufficient history. */
    profit_factor: number | null;
    /** Share of the trader's last 30 days with realized P&L that closed positive, 0-1 (higher is more consistent). A day with no realized P&L is not one of them, so the window can span months. null below 10 such days; null never means 0. */
    edge_consistency: number | null;
    /** Cross-sectional percentile rank of the trader's Sharpe ratio versus all traders, 0-100. null when insufficient history. */
    sharpe_percentile: number | null;
    /** Cross-sectional percentile rank of profit factor versus all traders, 0-100. null when insufficient history. */
    pf_percentile: number | null;
    /** Cross-sectional percentile rank of edge consistency versus all traders, 0-100. null when insufficient history. */
    consistency_percentile: number | null;
  };
  last_active?: string;
  synced_at?: string;
  /** synced, unknown, or pending. */
  sync_status?: string;
  /** Data age and coverage for this trader body. Always present. Its five groups are sync (traders.last_synced, covering pnl.total, pnl.realized, stats.markets_traded, stats.win_rate, stats.daily_win_rate, last_active, synced_at and sync_status), ranking (trader_rankings.computed_at, covering grade, score, streak_tier, forecast_score and forecast_evidence), leaderboard_rank (leaderboard_rank_refresh_state.completed_at, the completion time of the latest fully completed global rank refresh, covering rank), volume (trader_usd_volume.observed_at, covering stats.total_volume) and positions (trader_position_snapshots.last_refreshed_at with traders.last_synced as fallback, covering pnl.unrealized, the open-position aggregate). The positions clock is the latest successful /positions snapshot when one exists, otherwise the last completed trader sync; it does not date closed or native accounting values. A rank or position value remains unknown or unavailable when its clock or value is absent. For an unknown wallet every group is unavailable. If the open-position read itself fails, positions is unavailable with a reason that says so, pnl.unrealized is absent, and the body is answered fresh (meta.cached false) and is not kept for later callers. */
  data_quality: DataQuality;
  /** Field-level trust metadata. Present only when expand=trust or expand[]=trust is requested. */
  trust?: TraderTrust;
  /** Current evidence for observed and known categories (expand=categories or expand[]=categories). Omitted unless expanded. Includes insufficient, stale, unknown and degraded rows; absence of a category is not proof of skill. The global grade is unchanged. */
  category_records?: CategorySkillV2[];
  category_skill_model?: CategorySkillModelReadiness;
};

export type TraderCategoryRecord = {
  /** Canonical category bucket, for example Soccer, Esports, Tennis. Esports is one bucket, and the Esports record carries its per-game records in games. */
  category: string;
  /** Markets in this category the wallet closed with a profit. */
  wins: number;
  /** Markets it closed with a profit or a loss. A market that resolved at exactly zero P&L is in neither count, so this is not the wallet's market count in the category. */
  decided: number;
  /** wins / decided in [0,1], truncated to four decimals. Null when status is not_enough_data. */
  win_rate: number | null;
  /** measured: decided cleared min_decided_for_win_rate and win_rate carries the rate. not_enough_data: the counts are real but the sample is under the floor, so no percent is published. A failed read is an error response, never a status value. */
  status: "measured" | "not_enough_data";
  /** The wallet's record per esports title, busiest first. Present only on the Esports record, and only when the wallet has a settled market in at least one title; absent on every other category and on an Esports record whose markets are all in series that are not games (skin-price indices, streamer props) or carry no series. Absent means no per-game record, the same rule as an absent category. Each entry's decided is a subset of the Esports record's, read in the same statement from the same daily rebuild. */
  games?: TraderEsportsGameRecord[];
};

export type TraderCategoryRecords = {
  /** Prefixed trader id (trd_<wallet>). */
  id: string;
  /** Resolved wallet address, lowercased. */
  address: string;
  /** Which sample the counts come from: every settled market in the category, at any position size. category_strengths on the trader endpoint reads the floored calibration sample instead, so the two differ in both directions: measured on production 2026-09-22 over the 122,497 wallet-category pairs with at least 20 decided markets on both bases, the floored rate was higher in 56.5% of pairs and lower in 34.5%, median +0.6 points, p10 -4.6, p90 +9.8, with 14.0% of pairs 10 points apart or more. Neither corrects the other. */
  basis: "settled_markets_all_sizes";
  /** Decided markets a category needs before win_rate is served. Published so a caller can apply its own sample rule to the raw counts. */
  min_decided_for_win_rate: number;
  /** When the served records were last rebuilt (RFC3339, Z): the newest stamp among every row served, game rows included, which the daily rebuild writes in one transaction. Null when the wallet has no record at all. */
  computed_at: string | null;
  /** One entry per canonical category with at least one decided market, ordered by decided descending then category. A category with no decided market is omitted. The Esports entry carries its per-game records in games. */
  records: TraderCategoryRecord[];
};

export type TraderContext = {
  trader: Trader;
  /** Aggregate position and P&L coverage for the trader. Omitted entirely (key absent, never null) when the trader is not in the local database or native net economics is unavailable. Realized fields remain numbers when present, including a genuine zero. */
  position_summary?: {
    /** Provider markets_traded count when known; null when the provider total is unavailable. */
    markets_total: number | null;
    /** Markets with locally synced position rows. */
    markets_synced: number;
    /** Synced markets that have resolved. */
    markets_resolved: number;
    /** Synced markets still open with residual value (open positions with current value > 0). */
    markets_open: number;
    /** markets_synced divided by markets_total when the provider total is known (capped at 1.0); 0.0-1.0. When markets_total is unknown or not positive (null, 0, or negative), this is 1.0 if any markets are synced (else 0.0), so cross-check markets_total before treating 1.0 as full coverage. */
    sync_coverage: number;
    /** Native net realized P&L (USD) including credited rebates, minus the stored realized component of open positions with positive current value. Rebates are credited to the account, not to a position, so every credited rebate stays in this figure. NUMERIC arithmetic precedes conversion to a JSON number. */
    synced_realized_pnl: number;
    /** Native net realized P&L (USD) including credited rebates, read directly from the accounting snapshot. Position sync_coverage is separate from this accounting basis. */
    total_realized_pnl: number;
    /** Mark-to-market unrealized P&L (USD) on open positions. */
    unrealized_mtm: number;
    /** Cost basis (USD) currently tied up in open positions. */
    cost_basis_locked: number;
    /** Win rate as a percentage (0-100): resolved_wins over resolved_decided. A resolved market that settled at exactly zero realized P&L (a void, a refund, a fully hedged position) is neither a win nor a loss and is not in the denominator, the same rule the leaderboard applies; null when no resolved market was decided. */
    resolved_win_rate: number | null;
    /** Resolved markets that settled at positive realized P&L: the win-rate numerator. Additive; null only on a summary cached before the field existed. */
    resolved_wins: number | null;
    /** Resolved markets that settled at a non-zero realized P&L: the win-rate denominator. At most markets_resolved; the difference is markets settled at exactly zero or with an unknown P&L. Additive; null only on a summary cached before the field existed. */
    resolved_decided: number | null;
    /** RFC3339 freshness of the served OPEN-position data: the trader's latest /positions snapshot, else the last completed sync. The snapshot advances ONLY open positions, so read this as the open-position freshness clock -- the resolved/closed aggregates on this same summary (markets_resolved, resolved_win_rate) advance only on a full sync. The value is the /positions snapshot instant when one exists, so it is typically at or just before the trader-level last sync on a normal sync, and can be AFTER it while the active-view loop refreshes open positions between full syncs. This clock does not establish native accounting freshness. Always present on the wire (serialized as JSON null when the trader has neither a snapshot nor a sync); never omitted. */
    as_of: string | null;
  };
  /** RFC3339 freshness of the OPEN-position-level data: when a position_summary is present this mirrors its as_of byte-for-byte (latest /positions snapshot, else last completed sync) -- the open-position freshness clock, since the snapshot advances only open positions; otherwise the trader's last completed sync, even if an unserved position snapshot exists. Null when the selected clock is unavailable; a missing breakdown does not establish position or accounting freshness. */
  data_as_of: string | null;
  /** Human-readable statement of the point-in-time snapshot semantics (data_as_of is the open-position clock -- the latest /positions snapshot, else the last completed sync; the snapshot advances only open positions, so resolved counts and win rate date to the last full sync; native realized P&L follows its accounting snapshot -- not a live feed; re-fetch for fresher data). */
  freshness_note: string;
};

export type TraderEsportsGameRecord = {
  /** The game, by the same name every holder chip carries in category_win_rate_game: LoL, CS2, Dota 2, Valorant, Call of Duty, Honor of Kings, Mobile Legends: Bang Bang, Overwatch, Rainbow Six Siege, Rocket League or StarCraft II. Match a chip to this row by string equality. */
  game: string;
  /** The Polymarket series slug the record is keyed on: league-of-legends, counter-strike, dota-2, valorant, call-of-duty, honor-of-kings, mobile-legends-bang-bang, overwatch, rainbow-six-siege, rocket-league or starcraft-2. The stable key; game is the label. */
  series_slug: string;
  /** Markets in this game the wallet closed with a profit. */
  wins: number;
  /** Markets in this game it closed with a profit or a loss. A subset of the parent Esports record's decided: the two are read from the same daily rebuild. */
  decided: number;
  /** wins / decided in [0,1], truncated to four decimals. Null when status is not_enough_data. */
  win_rate: number | null;
  /** The same rule as the parent record: measured when decided cleared min_decided_for_win_rate, not_enough_data when the counts are real but the sample is under the floor. A chip on a market in this game shows this row's rate when it is measured and the Esports bucket's otherwise. */
  status: "measured" | "not_enough_data";
};

export type TraderExportArtifactManifest = {
  /** Version of the artifact manifest contract. */
  manifest_version: string;
  /** Serialization used for the decompressed content. */
  format: "json" | "ndjson" | "csv";
  /** Stable schema identifier for the selected serialization. */
  schema_version: "trader-export-json-v1" | "trader-export-ndjson-v1" | "trader-export-csv-v1";
  /** Sections represented by the artifact. JSON and NDJSON carry the full envelope and trades; CSV carries trade rows only. */
  coverage: "full_envelope_and_trades" | "trades_only";
  generation: TraderExportGeneration;
  /** Number of trade rows written. */
  row_count: number;
  /** Exact byte count of the decompressed content stream clients receive. */
  content_size_bytes: number;
  /** Lowercase SHA-256 of the decompressed content bytes. */
  content_sha256: string;
  /** Exact byte count of the gzip-compressed bytes stored by the object provider. */
  compressed_size_bytes: number;
  /** Lowercase SHA-256 of the stored gzip bytes; the multipart ETag is not used as this checksum. */
  compressed_sha256: string;
};

